(() => {
  const STORAGE_KEY = 'apoRentalDraftV2';
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];

  function readDraft() {
    try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'); }
    catch { return {}; }
  }
  function writeDraft(next) {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...readDraft(), ...next })); }
    catch {}
  }
  function toObject(form) {
    const out = {};
    new FormData(form).forEach((v, k) => { if (String(v).trim()) out[k] = String(v).trim(); });
    return out;
  }
  function todayISO() {
    const d = new Date();
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 10);
  }

  const navToggle = $('[data-menu-toggle]');
  const navLinks = $('[data-nav-links]');
  if (navToggle && navLinks) {
    navToggle.addEventListener('click', () => {
      const open = navLinks.classList.toggle('open');
      navToggle.setAttribute('aria-expanded', String(open));
    });
    $$('a', navLinks).forEach(a => a.addEventListener('click', () => navLinks.classList.remove('open')));
  }

  const pickupInputs = $$('input[name="pickupDate"]');
  const dropInputs = $$('input[name="dropoffDate"]');
  const today = todayISO();
  pickupInputs.forEach(input => input.min = today);
  dropInputs.forEach(input => input.min = today);
  function syncDropMin(pickup) {
    const form = pickup.closest('form');
    const drop = form?.querySelector('input[name="dropoffDate"]');
    if (!drop) return;
    drop.min = pickup.value || today;
    if (pickup.value && drop.value && drop.value < pickup.value) drop.value = pickup.value;
  }
  pickupInputs.forEach(input => {
    syncDropMin(input);
    input.addEventListener('change', () => syncDropMin(input));
  });

  const params = new URLSearchParams(location.search);
  const draft = readDraft();
  const queryClass = params.get('class');
  const queryLocation = params.get('location');
  if (queryClass) draft.vehicleClass = queryClass;
  if (queryLocation) draft.deliveryLocation = queryLocation;

  $$('form').forEach(form => {
    Object.entries(draft).forEach(([name, value]) => {
      const field = form.elements?.namedItem?.(name);
      if (!field || !value || field.type === 'submit') return;
      if (field instanceof RadioNodeList) return;
      if ([...field.options || []].length) {
        const option = [...field.options].find(o => o.value.toLowerCase() === String(value).toLowerCase());
        if (option) field.value = option.value;
      } else if (!field.value) {
        field.value = value;
      }
    });
  });

  function setVehicleClass(value, scroll = false) {
    if (!value) return;
    writeDraft({ vehicleClass: value });
    $$('select[name="vehicleClass"]').forEach(select => {
      const match = [...select.options].find(o => o.value.toLowerCase() === value.toLowerCase());
      if (match) select.value = match.value;
    });
    $$('.reserve-class').forEach(card => {
      const selected = (card.dataset.vehicleClass || '').toLowerCase() === value.toLowerCase();
      card.classList.toggle('selected', selected);
      card.setAttribute('aria-selected', String(selected));
    });
    if (scroll) $('#request')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
  if (draft.vehicleClass) setVehicleClass(draft.vehicleClass);
  $$('.reserve-class').forEach(card => {
    card.setAttribute('role', 'button');
    card.setAttribute('tabindex', '0');
    const activate = () => setVehicleClass(card.dataset.vehicleClass || '', true);
    card.addEventListener('click', activate);
    card.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); activate(); } });
  });

  $$('[data-request-class]').forEach(btn => {
    btn.addEventListener('click', () => {
      const vehicleClass = btn.dataset.requestClass || '';
      writeDraft({ vehicleClass });
      location.href = `/reserve?class=${encodeURIComponent(vehicleClass)}`;
    });
  });

  const filterButtons = $$('[data-filter-class]');
  if (filterButtons.length) {
    let active = '';
    filterButtons.forEach(btn => btn.addEventListener('click', () => {
      const next = btn.dataset.filterClass || '';
      active = active === next ? '' : next;
      filterButtons.forEach(b => {
        const on = (b.dataset.filterClass || '') === active;
        b.classList.toggle('selected', on);
        b.setAttribute('aria-pressed', String(on));
      });
      $$('.vehicle-card[data-vehicle-class]').forEach(card => {
        const show = !active || (card.dataset.vehicleClass || '').toLowerCase() === active.toLowerCase();
        card.hidden = !show;
      });
      $('.fleet-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }));
  }

  $$('form[data-flow="quick"]').forEach(form => {
    form.addEventListener('submit', e => {
      e.preventDefault();
      const data = toObject(form);
      if (data.pickupDate && data.dropoffDate && data.dropoffDate < data.pickupDate) {
        form.querySelector('input[name="dropoffDate"]')?.focus();
        alert('Drop off date must be on or after the pick up date.');
        return;
      }
      writeDraft(data);
      location.href = `/reserve${data.vehicleClass ? `?class=${encodeURIComponent(data.vehicleClass)}` : ''}`;
    });
  });

  const modal = $('[data-modal]');
  const summary = $('[data-reservation-summary]');
  const mailBtn = $('[data-email-request]');
  function closeModal() {
    modal?.classList.remove('open');
    modal?.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('modal-open');
  }
  function openModal() {
    if (!modal) return;
    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');
    document.body.classList.add('modal-open');
    $('#modal-name')?.focus();
  }
  $$('[data-close-modal]').forEach(btn => btn.addEventListener('click', closeModal));
  modal?.addEventListener('click', e => { if (e.target === modal) closeModal(); });

  function updateMailLink() {
    if (!mailBtn) return;
    const d = readDraft();
    const lines = [
      'A Priority One rental request', '',
      `Name: ${d.name || ''}`,
      `Phone: ${d.phone || ''}`,
      `Email: ${d.email || ''}`,
      `Pick up date: ${d.pickupDate || ''}`,
      `Drop off date: ${d.dropoffDate || ''}`,
      `Pick up location: ${d.pickupLocation || d.deliveryLocation || ''}`,
      `Drop off location: ${d.dropoffLocation || d.deliveryLocation || ''}`,
      `Vehicle class: ${d.vehicleClass || ''}`,
      `Notes: ${d.notes || ''}`,
      '',
      'Please confirm availability and the rate for this request.'
    ];
    mailBtn.href = `mailto:info@apriorityone.com?subject=${encodeURIComponent('Rental Request')}&body=${encodeURIComponent(lines.join('\n'))}`;
  }

  $$('form[data-flow="reserve"]').forEach(form => {
    form.addEventListener('submit', e => {
      e.preventDefault();
      const data = toObject(form);
      if (data.pickupDate && data.dropoffDate && data.dropoffDate < data.pickupDate) {
        form.querySelector('input[name="dropoffDate"]')?.focus();
        alert('Drop off date must be on or after the pick up date.');
        return;
      }
      writeDraft(data);
      const vehicleClass = data.vehicleClass || readDraft().vehicleClass || 'vehicle';
      const location = data.deliveryLocation || data.pickupLocation || readDraft().deliveryLocation || 'your requested location';
      if (summary) summary.textContent = `Review your ${vehicleClass} request for ${location}. A Priority One will confirm availability and your rate personally.`;
      const current = readDraft();
      [['modal-name','name'],['modal-phone','phone'],['modal-email','email'],['modal-notes','notes']].forEach(([id,key]) => {
        const el = document.getElementById(id); if (el && current[key] && !el.value) el.value = current[key];
      });
      updateMailLink();
      openModal();
    });
  });

  $$('#modal-name,#modal-phone,#modal-email,#modal-notes').forEach(input => {
    input.addEventListener('input', () => {
      const map = { 'modal-name':'name','modal-phone':'phone','modal-email':'email','modal-notes':'notes' };
      writeDraft({ [map[input.id]]: input.value.trim() });
      updateMailLink();
    });
  });

  const faqModal = $('[data-faq-modal]');
  $$('[data-open-faq]').forEach(link => link.addEventListener('click', e => {
    e.preventDefault();
    faqModal?.classList.add('open');
    faqModal?.setAttribute('aria-hidden', 'false');
    document.body.classList.add('modal-open');
  }));
  $$('[data-close-faq]').forEach(btn => btn.addEventListener('click', () => {
    faqModal?.classList.remove('open');
    faqModal?.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('modal-open');
  }));
  faqModal?.addEventListener('click', e => {
    if (e.target === faqModal) {
      faqModal.classList.remove('open');
      faqModal.setAttribute('aria-hidden', 'true');
      document.body.classList.remove('modal-open');
    }
  });

  const quotes = $$('.quote[data-testimonial]');
  const dots = $$('.dots span');
  let quoteIndex = 0;
  function renderQuote() {
    quotes.forEach((q, i) => q.classList.toggle('testimonial-active', i === quoteIndex));
    dots.forEach((d, i) => d.classList.toggle('active', i === quoteIndex));
  }
  $('[data-testimonial-prev]')?.addEventListener('click', () => { quoteIndex = (quoteIndex - 1 + quotes.length) % quotes.length; renderQuote(); });
  $('[data-testimonial-next]')?.addEventListener('click', () => { quoteIndex = (quoteIndex + 1) % quotes.length; renderQuote(); });
  dots.forEach((d, i) => d.addEventListener('click', () => { quoteIndex = Math.min(i, Math.max(0, quotes.length - 1)); renderQuote(); }));
  if (quotes.length) renderQuote();

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') { closeModal(); faqModal?.classList.remove('open'); document.body.classList.remove('modal-open'); }
  });
})();
